# ── TicketTool/multi_embed.py ─────────────────────────────────────────────
_TT_multi_embed_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.multi_embed — Multi-Embed Panel Messages + Advanced Moderator
Messages (Tier 3 Features #9 + #10).

Two related capabilities:

1. MULTI-EMBED PANEL MESSAGES (#10)
   Replaces the single embed_title/embed_description on ticket_panels with
   support for up to 10 embeds per panel, each with up to 25 fields. The
   embeds are stored in the panel_embeds table and rendered in order_index.

   embed_data JSON shape:
     {
       "title": "...",
       "description": "...",
       "color": "0x5865F2",       # hex string or int
       "url": "...",
       "thumbnail": {"url": "..."},
       "image": {"url": "..."},
       "author": {"name": "...", "icon_url": "..."},
       "footer": {"text": "...", "icon_url": "..."},
       "fields": [{"name": "...", "value": "...", "inline": true}, ...],
       "timestamp": true           # adds current timestamp
     }

2. ADVANCED MODERATOR MESSAGES (#9)
   Customizable messages shown on ticket lifecycle events (close, reopen,
   delete, claim, unclaim). Each message supports:
     - Plain text content (variable-rendered)
     - Multiple embeds (same shape as above)
     - Buttons (up to 25 per message)

   button JSON shape:
     {"label": "...", "style": "primary|secondary|success|danger|link",
      "emoji": "🎫", "custom_id": "mod_action:close", "url": "..."}

   Configured per-panel per-event-type.

Integration:
  * TicketTool.wiring.on_ticket_close -> moderator_messages.send_for_event(... 'close')
  * TicketTool.wiring.on_ticket_reopen -> moderator_messages.send_for_event(... 'reopen')
  * TicketTool.wiring.on_ticket_claim -> moderator_messages.send_for_event(... 'claim')
  * TicketTool.wiring.on_ticket_unclaim -> moderator_messages.send_for_event(... 'unclaim')
  * TicketPanelView (Bot.py) -> multi_embed.build_panel_message(panel) to
    render multi-embed panel messages instead of the single embed.
'''

from __future__ import annotations

import logging
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

import discord

from .db import PremiumDB
from . import variables


# =====================================================================
# EMBED DATA -> discord.Embed
# =====================================================================

MAX_EMBEDS_PER_MESSAGE = 10
MAX_FIELDS_PER_EMBED = 25


def _parse_color(color_val) -> int:
    '''Accept int, hex string ('0x5865F2' or '#5865F2'), or plain hex.'''
    if color_val is None:
        return 0x5865F2
    if isinstance(color_val, (int, float)):
        return int(color_val)
    s = str(color_val).strip().lstrip('#').lstrip('0x').lstrip('0X')
    try:
        return int(s, 16)
    except ValueError:
        return 0x5865F2


def _parse_style(style_val) -> discord.ButtonStyle:
    '''Accept string or int style.'''
    if isinstance(style_val, (int, float)):
        try:
            return discord.ButtonStyle(int(style_val))
        except (ValueError, TypeError):
            return discord.ButtonStyle.secondary
    s = str(style_val or 'secondary').strip().lower()
    return {
        'primary': discord.ButtonStyle.primary,
        'secondary': discord.ButtonStyle.secondary,
        'success': discord.ButtonStyle.success,
        'danger': discord.ButtonStyle.danger,
        'link': discord.ButtonStyle.link,
    }.get(s, discord.ButtonStyle.secondary)


def embed_from_data(data: Dict, *, ctx: Optional[variables.VariableContext] = None) -> discord.Embed:
    '''Build a discord.Embed from a JSON-serializable embed_data dict.

    If `ctx` is provided, all string values are rendered through the variable
    engine first (so {ticket.user}, {claim.user}, etc. work in embed fields).
    '''
    def _r(text):
        '''Render a string through the variable engine if ctx is provided.'''
        if not text or ctx is None:
            return text or ''
        return variables.render(str(text), ctx)

    title = _r(data.get('title')) or None
    description = _r(data.get('description')) or None
    color = _parse_color(data.get('color'))
    embed = discord.Embed(
        title=title[:256] if title else None,
        description=description[:4096] if description else None,
        color=discord.Color(color),
    )
    if data.get('url'):
        embed.url = str(data['url'])
    if data.get('timestamp'):
        embed.timestamp = datetime.now(timezone.utc)
    # Thumbnail
    thumb = data.get('thumbnail') or {}
    if isinstance(thumb, dict) and thumb.get('url'):
        embed.set_thumbnail(url=str(thumb['url']))
    elif isinstance(thumb, str):
        embed.set_thumbnail(url=thumb)
    # Image
    image = data.get('image') or {}
    if isinstance(image, dict) and image.get('url'):
        embed.set_image(url=str(image['url']))
    elif isinstance(image, str):
        embed.set_image(url=image)
    # Author
    author = data.get('author') or {}
    if isinstance(author, dict) and author.get('name'):
        embed.set_author(
            name=_r(author['name'])[:256],
            url=str(author.get('url') or ''),
            icon_url=str(author.get('icon_url') or '') or None,
        )
    # Footer
    footer = data.get('footer') or {}
    if isinstance(footer, dict) and footer.get('text'):
        embed.set_footer(
            text=_r(footer['text'])[:2048],
            icon_url=str(footer.get('icon_url') or '') or None,
        )
    # Fields
    for field in (data.get('fields') or [])[:MAX_FIELDS_PER_EMBED]:
        if not isinstance(field, dict):
            continue
        name = _r(field.get('name') or '\u200b')[:256]
        value = _r(field.get('value') or '\u200b')[:1024]
        inline = bool(field.get('inline', True))
        embed.add_field(name=name, value=value, inline=inline)
    return embed


def embed_to_data(embed: discord.Embed) -> Dict:
    '''Inverse of embed_from_data: extract a JSON-serializable dict from a
    live discord.Embed. Used when migrating existing single-embed panels.
    '''
    data = {}
    if embed.title:
        data['title'] = embed.title
    if embed.description:
        data['description'] = embed.description
    if embed.color:
        data['color'] = f"0x{embed.color.value:06X}"
    if embed.url:
        data['url'] = embed.url
    if embed.thumbnail and embed.thumbnail.url:
        data['thumbnail'] = {'url': embed.thumbnail.url}
    if embed.image and embed.image.url:
        data['image'] = {'url': embed.image.url}
    if embed.author:
        data['author'] = {
            'name': embed.author.name,
            'icon_url': embed.author.icon_url or '',
        }
    if embed.footer:
        data['footer'] = {
            'text': embed.footer.text or '',
            'icon_url': embed.footer.icon_url or '',
        }
    if embed.fields:
        data['fields'] = [
            {'name': f.name, 'value': f.value, 'inline': f.inline}
            for f in embed.fields
        ]
    return data


# =====================================================================
# MULTI-EMBED PANEL MESSAGES (Feature #10)
# =====================================================================

def add_panel_embed(pdb: PremiumDB, *, panel_id: str, guild_id: int,
                    embed_data: Dict, order_index: Optional[int] = None) -> str:
    '''Add an embed to a panel. Auto-assigns order_index if not provided.'''
    existing = pdb.list_panel_embeds(panel_id)
    if len(existing) >= MAX_EMBEDS_PER_MESSAGE:
        raise ValueError(f"Panel already has the maximum of {MAX_EMBEDS_PER_MESSAGE} embeds.")
    if order_index is None:
        order_index = len(existing)
    return pdb.save_panel_embed({
        'panel_id': panel_id,
        'guild_id': guild_id,
        'order_index': order_index,
        'embed_data': embed_data,
        'is_active': 1,
    })


def update_panel_embed(pdb: PremiumDB, embed_id: str, embed_data: Dict) -> bool:
    '''Update an existing panel embed's data.'''
    embeds = pdb.list_panel_embeds('')  # need the specific one
    # We need to fetch the embed by ID — list_panel_embeds is per-panel, so
    # we'll use the raw accessor.
    # Actually we can just call save_panel_embed with the existing ID.
    pdb.save_panel_embed({
        'embed_id': embed_id,
        'embed_data': embed_data,
        'is_active': 1,
    })
    return True


def remove_panel_embed(pdb: PremiumDB, embed_id: str) -> bool:
    return pdb.delete_panel_embed(embed_id)


def reorder_panel_embeds(pdb: PremiumDB, panel_id: str, embed_order: List[str]) -> None:
    pdb.reorder_panel_embeds(panel_id, embed_order)


def build_panel_embeds(pdb: PremiumDB, panel: Dict,
                        *, ctx: Optional[variables.VariableContext] = None) -> List[discord.Embed]:
    '''Build a list of discord.Embed objects for a panel.

    Falls back to the single embed_title/embed_description on the panel row
    if no multi-embeds are configured (backward compatible).
    '''
    panel_id = panel.get('panel_id')
    embeds: List[discord.Embed] = []
    if panel_id:
        rows = pdb.list_panel_embeds(panel_id)
        for row in rows:
            try:
                embeds.append(embed_from_data(row.get('embed_data', {}), ctx=ctx))
            except Exception as exc:
                logging.warning(f"[multi_embed] failed to build embed {row.get('embed_id')}: {exc}")
    if not embeds:
        # Backward-compatible fallback: build a single embed from the panel row.
        embed = discord.Embed(
            title=panel.get('embed_title') or 'Support Tickets',
            description=panel.get('embed_description') or 'Click the button below to create a ticket.',
            color=discord.Color(panel.get('embed_color', 0x5865F2)),
        )
        if panel.get('embed_thumbnail'):
            embed.set_thumbnail(url=panel['embed_thumbnail'])
        if panel.get('embed_image'):
            embed.set_image(url=panel['embed_image'])
        embeds.append(embed)
    return embeds[:MAX_EMBEDS_PER_MESSAGE]


def is_multi_embed_enabled(panel: Optional[Dict]) -> bool:
    if not panel:
        return False
    return bool(int(panel.get('use_multi_embed', 0) or 0))


def enable_multi_embed(pdb: PremiumDB, data_manager, panel_id: str, *, enabled: bool) -> bool:
    try:
        panel = data_manager.load_ticket_panel(panel_id)
        if not panel:
            return False
        panel['use_multi_embed'] = 1 if enabled else 0
        data_manager.save_ticket_panel(panel)
        return True
    except Exception as exc:
        logging.warning(f"[multi_embed] enable_multi_embed failed: {exc}")
        return False


# =====================================================================
# ADVANCED MODERATOR MESSAGES (Feature #9)
# =====================================================================

MODERATOR_EVENT_TYPES = {'close', 'reopen', 'delete', 'claim', 'unclaim', 'create'}


def set_moderator_message(pdb: PremiumDB, *, panel_id: str, guild_id: int,
                           event_type: str, content: Optional[str] = None,
                           embeds: Optional[List[Dict]] = None,
                           buttons: Optional[List[Dict]] = None,
                           enabled: bool = True) -> str:
    '''Create or update a moderator message for a panel + event.'''
    if event_type not in MODERATOR_EVENT_TYPES:
        raise ValueError(f"Invalid event_type. Use one of: {', '.join(sorted(MODERATOR_EVENT_TYPES))}")
    return pdb.upsert_moderator_message({
        'panel_id': panel_id,
        'guild_id': guild_id,
        'event_type': event_type,
        'content': content,
        'embeds': embeds or [],
        'buttons': buttons or [],
        'enabled': enabled,
    })


def get_moderator_message(pdb: PremiumDB, panel_id: str, event_type: str) -> Optional[Dict]:
    return pdb.get_moderator_message(panel_id, event_type)


def delete_moderator_message(pdb: PremiumDB, message_id: str) -> bool:
    return pdb.delete_moderator_message(message_id)


def build_buttons_view(buttons_data: List[Dict]) -> Optional[discord.ui.View]:
    '''Build a discord.ui.View from a list of button config dicts.'''
    if not buttons_data:
        return None
    view = discord.ui.View(timeout=None)
    for i, btn_data in enumerate(buttons_data[:25]):
        try:
            style = _parse_style(btn_data.get('style', 'secondary'))
            label = str(btn_data.get('label', ''))[:80] or None
            emoji = btn_data.get('emoji') or None
            custom_id = btn_data.get('custom_id')
            url = btn_data.get('url')
            # Link buttons use url; action buttons use custom_id.
            if style == discord.ButtonStyle.link and url:
                btn = discord.ui.Button(
                    style=style, label=label, emoji=emoji, url=url,
                )
            else:
                if not custom_id:
                    custom_id = f"modbtn:{i}"
                btn = discord.ui.Button(
                    style=style, label=label, emoji=emoji, custom_id=custom_id,
                )
            view.add_item(btn)
        except Exception as exc:
            logging.warning(f"[multi_embed] button build failed: {exc}")
    return view


async def send_moderator_message(*, bot, pdb: PremiumDB, channel: discord.TextChannel,
                                   panel_id: str, event_type: str,
                                   ticket: Dict, panel: Optional[Dict] = None,
                                   actor: Optional[discord.Member] = None,
                                   extra: Optional[Dict] = None) -> bool:
    '''Send the configured moderator message for a panel + event.

    Returns True if a message was sent, False if no config exists or it's
    disabled.
    '''
    cfg = pdb.get_moderator_message(panel_id, event_type)
    if not cfg or not cfg.get('enabled'):
        return False

    # Build the variable context for rendering.
    claimer = None
    if ticket.get('claimed_by') and channel.guild:
        claimer = channel.guild.get_member(int(ticket['claimed_by']))
    ctx = variables.VariableContext(
        ticket=ticket,
        panel=panel or {},
        guild={'id': channel.guild.id, 'name': channel.guild.name},
        claim_user={'id': claimer.id, 'name': claimer.display_name} if claimer else {},
        acting_user={'id': actor.id, 'name': actor.display_name} if actor else {},
        extra=extra or {},
    )

    # Render content.
    content = None
    if cfg.get('content'):
        content = variables.render(cfg['content'], ctx)[:1900]

    # Build embeds.
    embeds: List[discord.Embed] = []
    for embed_data in (cfg.get('embeds') or [])[:MAX_EMBEDS_PER_MESSAGE]:
        try:
            embeds.append(embed_from_data(embed_data, ctx=ctx))
        except Exception as exc:
            logging.warning(f"[multi_embed] moderator embed build failed: {exc}")

    # Build buttons view.
    view = build_buttons_view(cfg.get('buttons') or [])

    # Send.
    try:
        # discord.py allows up to 10 embeds per message.
        if embeds and content:
            await channel.send(content=content, embeds=embeds[:10],
                                view=view)
        elif embeds:
            await channel.send(embeds=embeds[:10], view=view)
        elif content:
            await channel.send(content=content, view=view)
        else:
            return False  # nothing to send
        return True
    except discord.HTTPException as exc:
        logging.warning(f"[multi_embed] moderator message send failed: {exc}")
        return False
"""

# ── TicketTool/naming.py ─────────────────────────────────────────────
_TT_naming_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.naming — Advanced Ticket Naming + Variables (Tier 1 Features #5 + #8).

Adds:
  * Automatic ticket-naming templates per panel, with separate templates for
    open / closed / claimed tickets (Ticket Tool premium feature).
  * A guild-wide ticket counter ({ticket.count}) with configurable zero
    padding (e.g. #57 -> #0057 with padding=4). Supports up to 20 chars of
    padding (matches Ticket Tool's documented limit).
  * Full variable support in templates via TicketTool.variables.

Integration:
  * TicketToolSystem.create_ticket calls naming.compute_open_name(panel, ctx)
    to get the channel name + subject.
  * On close, naming.compute_closed_name(...) can rename the channel.
  * On claim, naming.compute_claimed_name(...) can rename the channel.

Everything is pure logic + DB; no discord imports here except the type hints.
'''

from __future__ import annotations

import logging
import re
from datetime import datetime, timezone
from typing import Any, Dict, Optional, Tuple

from . import variables
from .db import PremiumDB


# Discord channel-name limits (we enforce these so templates can never
# produce an invalid name and crash create_text_channel).
MAX_CHANNEL_NAME_LEN = 100
MAX_SUBJECT_LEN = 1000


def _sanitize_channel_name(name: str) -> str:
    '''Make a string safe for use as a Discord channel name.

    Discord allows lowercase letters, numbers, '-' and '_'. Spaces become '-'.
    Everything else is stripped. Lowercased. Truncated to 100 chars.
    '''
    if not name:
        return 'ticket'
    cleaned = []
    for ch in name.strip().lower():
        if ch.isalnum() or ch in '-_':
            cleaned.append(ch)
        elif ch.isspace():
            cleaned.append('-')
        # else: drop it
    result = ''.join(cleaned)
    # Collapse runs of '-' and strip leading/trailing '-'
    result = re.sub(r'-+', '-', result).strip('-')
    if not result:
        result = 'ticket'
    return result[:MAX_CHANNEL_NAME_LEN]


def _pad_number(value: int, width: int) -> str:
    '''Zero-pad a number to `width` digits (max 20, matching Ticket Tool).'''
    if width <= 0:
        return str(value)
    width = min(width, 20)
    return str(value).zfill(width)


# =====================================================================
# TEMPLATE RESOLUTION
# =====================================================================

def get_config(pdb: PremiumDB, panel_id: str) -> Optional[Dict]:
    return pdb.get_naming(panel_id)


def _padded_count(cfg: Optional[Dict], count) :
    '''Apply the panel's configured zero-padding to a ticket number.

    TicketTool "Ticket Padding" premium feature: pad(57, 4) -> '0057'.
    Previously the padding config was stored but never applied to the
    {ticket.count} variable in naming templates.
    '''
    if cfg is None or count is None:
        return count
    try:
        width = int(cfg.get('number_padding', 0) or 0)
    except (TypeError, ValueError):
        width = 0
    if width <= 0:
        return count
    return _pad_number(int(count), width)


def compute_open_name(
    pdb: PremiumDB,
    panel: Dict,
    *,
    guild: Dict,
    ticket_id: str,
    creator: Dict,
    ticket_count: int,
    subject: Optional[str] = None,
    tz_offset_hours: float = 0.0,
) -> Tuple[str, str]:
    '''Compute (channel_name, subject) for a newly-opened ticket.

    Falls back to the existing Bot.py naming convention
    (`ticket-{username}-{ticket_id}`) when no template is configured, so the
    behavior is identical to before unless the owner opts in.
    '''
    panel_id = panel.get('panel_id')
    cfg = pdb.get_naming(panel_id) if panel_id else None
    count = ticket_count or pdb.reserve_ticket_number_safe(guild.get('id', 0))

    ctx = variables.VariableContext(
        ticket={'ticket_id': ticket_id, 'subject': subject,
                'creator_id': creator.get('id') if creator else None},
        ticket_count=_padded_count(cfg, count),
        panel=panel,
        guild=guild,
        acting_user=creator,
        extra={'ticket_creator_name': (creator or {}).get('name', '')},
        tz_offset_hours=tz_offset_hours,
    )

    if cfg and cfg.get('open_template'):
        rendered = variables.render(cfg['open_template'], ctx)
        channel_name = _sanitize_channel_name(rendered) or f'ticket-{ticket_id}'
    else:
        # Backward-compatible default: ticket-{username}-{ticket_id}
        uname = (creator or {}).get('name', 'user')
        safe_uname = ''.join(c if c.isalnum() or c == '-' else '-' for c in uname.lower())[:40]
        channel_name = f'ticket-{safe_uname}-{ticket_id}'[:MAX_CHANNEL_NAME_LEN]

    # Subject: use provided, else a template, else the panel name.
    rendered_subject = subject
    if not rendered_subject and cfg and cfg.get('open_template'):
        # If the owner used a {ticket.subject} var in the open template but
        # did not pass a subject, leave the subject blank (it can be set later).
        rendered_subject = ''
    return channel_name, (rendered_subject or '')[:MAX_SUBJECT_LEN]


def compute_closed_name(
    pdb: PremiumDB,
    panel: Dict,
    *,
    guild: Dict,
    ticket: Dict,
    ticket_count: Optional[int] = None,
    closer: Optional[Dict] = None,
    tz_offset_hours: float = 0.0,
) -> Optional[str]:
    '''Return the channel name to apply on close, or None to leave as-is.'''
    panel_id = panel.get('panel_id') if panel else None
    cfg = pdb.get_naming(panel_id) if panel_id else None
    if not cfg or not cfg.get('closed_template'):
        return None
    ctx = variables.VariableContext(
        ticket=ticket,
        ticket_count=_padded_count(cfg, ticket_count),
        panel=panel,
        guild=guild,
        acting_user=closer or {},
        extra={'ticket_creator_name': ''},
        tz_offset_hours=tz_offset_hours,
    )
    rendered = variables.render(cfg['closed_template'], ctx)
    return _sanitize_channel_name(rendered) or None


def compute_claimed_name(
    pdb: PremiumDB,
    panel: Dict,
    *,
    guild: Dict,
    ticket: Dict,
    claimer: Dict,
    ticket_count: Optional[int] = None,
    tz_offset_hours: float = 0.0,
) -> Optional[str]:
    '''Return the channel name to apply on claim, or None to leave as-is.'''
    panel_id = panel.get('panel_id') if panel else None
    cfg = pdb.get_naming(panel_id) if panel_id else None
    if not cfg or not cfg.get('claimed_template'):
        return None
    ctx = variables.VariableContext(
        ticket=ticket,
        ticket_count=_padded_count(cfg, ticket_count),
        panel=panel,
        guild=guild,
        claim_user=claimer,
        acting_user=claimer,
        extra={'ticket_creator_name': ''},
        tz_offset_hours=tz_offset_hours,
    )
    rendered = variables.render(cfg['claimed_template'], ctx)
    return _sanitize_channel_name(rendered) or None


def compute_unclaimed_name(
    pdb: PremiumDB,
    panel: Dict,
    *,
    guild: Dict,
    ticket: Dict,
    ticket_count: Optional[int] = None,
    tz_offset_hours: float = 0.0,
) -> Optional[str]:
    '''On unclaim, restore the open-template name (if configured).'''
    panel_id = panel.get('panel_id') if panel else None
    cfg = pdb.get_naming(panel_id) if panel_id else None
    if not cfg or not cfg.get('open_template'):
        return None
    ctx = variables.VariableContext(
        ticket=ticket,
        ticket_count=_padded_count(cfg, ticket_count),
        panel=panel,
        guild=guild,
        extra={'ticket_creator_name': ''},
        tz_offset_hours=tz_offset_hours,
    )
    rendered = variables.render(cfg['open_template'], ctx)
    return _sanitize_channel_name(rendered) or None


# =====================================================================
# COUNTER HELPERS
# =====================================================================

def reserve_number(pdb: PremiumDB, guild_id: int) -> int:
    '''Atomically reserve the next guild ticket number.'''
    return pdb.reserve_ticket_number(guild_id)


def pad(pdb: PremiumDB, panel_id: str, number: int) -> str:
    '''Apply a panel's configured padding to a ticket number.'''
    cfg = pdb.get_naming(panel_id)
    width = int(cfg.get('number_padding', 0)) if cfg else 0
    return _pad_number(number, width)


# Small wrapper used by compute_open_name when no count was supplied — keeps
# the public API simple while still reserving atomically.
def _reserve_safe(self, guild_id):
    try:
        return self.reserve_ticket_number(guild_id)
    except Exception:
        return 1

PremiumDB.reserve_ticket_number_safe = _reserve_safe  # type: ignore[attr-defined]
"""

# ── TicketTool/role_automation.py ─────────────────────────────────────────────
_TT_role_automation_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.role_automation — Open/Close/Claim Role Automation (Tier 1 Feature #3).

Per-panel rules that add/remove Discord roles on the ticket creator when:
  * the ticket is opened  (open_add_roles / open_remove_roles)
  * the ticket is closed  (close_add_roles / close_remove_roles)
  * the ticket is claimed  (claim_add_roles / claim_remove_roles — applied to CLAIMER)
  * the ticket is unclaimed (unclaim_add_roles / unclaim_remove_roles — applied to CLAIMER)

Integration (called from TicketTool.wiring):
  * on_ticket_create(...)   -> apply_open(...)
  * on_ticket_close(...)    -> apply_close(...)
  * on_ticket_claim(...)    -> apply_claim(...)
  * on_ticket_unclaim(...)  -> apply_unclaim(...)

All role mutations are best-effort: a missing role or permission failure is
logged and does not abort the surrounding ticket operation. This matches the
existing Bot.py convention (side effects never roll back the primary action).
'''

from __future__ import annotations

import logging
from typing import Dict, List, Optional

import discord

from .db import PremiumDB, _json_loads_list


EVENT_OPEN = 'open'
EVENT_CLOSE = 'close'
EVENT_CLAIM = 'claim'
EVENT_UNCLAIM = 'unclaim'

_VALID_EVENTS = {EVENT_OPEN, EVENT_CLOSE, EVENT_CLAIM, EVENT_UNCLAIM}


# =====================================================================
# CONFIG ACCESSORS
# =====================================================================

def get_config(pdb: PremiumDB, panel_id: str) -> Dict:
    cfg = pdb.get_role_automation(panel_id)
    if not cfg:
        return {
            'panel_id': panel_id,
            'open_add_roles': [], 'open_remove_roles': [],
            'close_add_roles': [], 'close_remove_roles': [],
            'claim_add_roles': [], 'claim_remove_roles': [],
            'unclaim_add_roles': [], 'unclaim_remove_roles': [],
        }
    return {
        'panel_id': panel_id,
        'open_add_roles': _json_loads_list(cfg.get('open_add_roles')),
        'open_remove_roles': _json_loads_list(cfg.get('open_remove_roles')),
        'close_add_roles': _json_loads_list(cfg.get('close_add_roles')),
        'close_remove_roles': _json_loads_list(cfg.get('close_remove_roles')),
        'claim_add_roles': _json_loads_list(cfg.get('claim_add_roles')),
        'claim_remove_roles': _json_loads_list(cfg.get('claim_remove_roles')),
        'unclaim_add_roles': _json_loads_list(cfg.get('unclaim_add_roles')),
        'unclaim_remove_roles': _json_loads_list(cfg.get('unclaim_remove_roles')),
    }


def save_config(pdb: PremiumDB, panel_id: str, guild_id: int, cfg: Dict) -> None:
    pdb.upsert_role_automation({**cfg, 'panel_id': panel_id, 'guild_id': guild_id})


def set_event_roles(pdb: PremiumDB, panel_id: str, guild_id: int, event: str,
                    *, add_roles: Optional[List[int]] = None,
                    remove_roles: Optional[List[int]] = None) -> None:
    '''Convenience setter for a single event's add/remove role lists.'''
    if event not in _VALID_EVENTS:
        raise ValueError(f"invalid event {event!r}")
    cfg = get_config(pdb, panel_id)
    if add_roles is not None:
        cfg[f'{event}_add_roles'] = [int(r) for r in add_roles]
    if remove_roles is not None:
        cfg[f'{event}_remove_roles'] = [int(r) for r in remove_roles]
    save_config(pdb, panel_id, guild_id, cfg)


# =====================================================================
# ROLE APPLICATION
# =====================================================================

async def _apply_to_member(member: discord.Member, *,
                           add: List[int], remove: List[int],
                           reason: str) -> Dict[str, List[int]]:
    '''Apply role add/remove to a member. Returns {'added':[...],'removed':[...]}.

    Silently skips roles that don't exist or that the bot can't manage
    (hierarchy / missing perms). Never raises.
    '''
    added: List[int] = []
    removed: List[int] = []
    guild = member.guild
    # Resolve role objects once.
    add_objs = [guild.get_role(int(rid)) for rid in add if rid]
    rem_objs = [guild.get_role(int(rid)) for rid in remove if rid]
    add_objs = [r for r in add_objs if r is not None]
    rem_objs = [r for r in rem_objs if r is not None]
    # Filter out roles the bot can't touch.
    me = guild.me
    bot_top = me.top_role.position if me.top_role else 0
    add_objs = [r for r in add_objs if r.position < bot_top and r not in member.roles]
    rem_objs = [r for r in rem_objs if r.position < bot_top and r in member.roles]
    if add_objs:
        try:
            await member.add_roles(*add_objs, reason=reason)
            added = [r.id for r in add_objs]
        except discord.Forbidden:
            logging.warning(f"[tickettool.role_auto] forbidden adding roles to {member}")
        except discord.HTTPException as exc:
            logging.warning(f"[tickettool.role_auto] add_roles HTTP error: {exc}")
    if rem_objs:
        try:
            await member.remove_roles(*rem_objs, reason=reason)
            removed = [r.id for r in rem_objs]
        except discord.Forbidden:
            logging.warning(f"[tickettool.role_auto] forbidden removing roles from {member}")
        except discord.HTTPException as exc:
            logging.warning(f"[tickettool.role_auto] remove_roles HTTP error: {exc}")
    return {'added': added, 'removed': removed}


async def apply_open(pdb: PremiumDB, member: discord.Member, panel: Optional[Dict]) -> Dict:
    '''Add/remove roles on the ticket creator when their ticket opens.'''
    if not panel:
        return {'added': [], 'removed': []}
    cfg = get_config(pdb, panel.get('panel_id'))
    return await _apply_to_member(
        member,
        add=cfg['open_add_roles'],
        remove=cfg['open_remove_roles'],
        reason=f"Ticket opened in panel {panel.get('name','?')}",
    )


async def apply_close(pdb: PremiumDB, member: discord.Member, panel: Optional[Dict]) -> Dict:
    '''Add/remove roles on the ticket creator when their ticket closes.'''
    if not panel:
        return {'added': [], 'removed': []}
    cfg = get_config(pdb, panel.get('panel_id'))
    return await _apply_to_member(
        member,
        add=cfg['close_add_roles'],
        remove=cfg['close_remove_roles'],
        reason=f"Ticket closed in panel {panel.get('name','?')}",
    )


async def apply_claim(pdb: PremiumDB, claimer: discord.Member, panel: Optional[Dict]) -> Dict:
    '''Add/remove roles on the CLAIMER when they claim a ticket.'''
    if not panel:
        return {'added': [], 'removed': []}
    cfg = get_config(pdb, panel.get('panel_id'))
    return await _apply_to_member(
        claimer,
        add=cfg['claim_add_roles'],
        remove=cfg['claim_remove_roles'],
        reason=f"Claimed ticket in panel {panel.get('name','?')}",
    )


async def apply_unclaim(pdb: PremiumDB, claimer: discord.Member, panel: Optional[Dict]) -> Dict:
    '''Reverse claim roles when a claim is released.'''
    if not panel:
        return {'added': [], 'removed': []}
    cfg = get_config(pdb, panel.get('panel_id'))
    # On unclaim: undo claim_add by removing, undo claim_remove by adding back.
    return await _apply_to_member(
        claimer,
        add=cfg['unclaim_add_roles'],
        remove=cfg['unclaim_remove_roles'],
        reason=f"Unclaimed ticket in panel {panel.get('name','?')}",
    )
"""

# ── TicketTool/scheduling.py ─────────────────────────────────────────────
_TT_scheduling_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.scheduling — Ticket Scheduling / Business Hours (Tier 1 Feature #4).

Per-panel availability windows. A panel can be open only during configured
periods (e.g. Mon-Fri 16:00-22:00, Sat-Sun 12:00-23:00). Roles can bypass the
schedule. Outside the schedule, the Create Ticket button shows a custom
"unavailable" message instead of opening a ticket.

Integration:
  * TicketPanelView.create_button checks scheduling.is_panel_open_now(...)
    BEFORE showing the questions modal / creating the channel. When closed,
    replies with the panel's unavailable_message.
  * Premium wiring re-evaluates panel messages on startup so the button state
    can be toggled if desired (optional; the check at click-time is the
    authoritative gate).
'''

from __future__ import annotations

import logging
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Tuple

from .db import PremiumDB, _json_loads_list


# Day-of-week mapping. 0=Monday ... 6=Sunday (Python weekday()).
# Schedules are stored with day names for human readability.
DAY_NAMES = ['monday', 'tuesday', 'wednesday', 'thursday',
             'friday', 'saturday', 'sunday']
DAY_INDEX = {name: i for i, name in enumerate(DAY_NAMES)}
WEEKDAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday'}
WEEKEND = {'saturday', 'sunday'}


# =====================================================================
# TIMEZONE HANDLING
# =====================================================================

# A small built-in offset table so users can pick a friendly timezone name
# without needing pytz (which may not be installed). Falls back to UTC.
# Offsets are in hours from UTC.
COMMON_TIMEZONES = {
    'UTC': 0.0,
    'ET': -5.0, 'EST': -5.0, 'EDT': -4.0,
    'CT': -6.0, 'CST': -6.0, 'CDT': -5.0,
    'MT': -7.0, 'MST': -7.0, 'MDT': -6.0,
    'PT': -8.0, 'PST': -8.0, 'PDT': -7.0,
    'GMT': 0.0, 'BST': 1.0, 'CET': 1.0, 'CEST': 2.0,
    'EET': 2.0, 'EEST': 3.0,
    'AEST': 10.0, 'AEDT': 11.0,
    'IST': 5.5, 'PKT': 5.0, 'JST': 9.0,
}


def tz_offset_hours(tz_name: str) -> float:
    if not tz_name:
        return 0.0
    return COMMON_TIMEZONES.get(tz_name.strip(), 0.0)


def now_in_tz(tz_name: str) -> datetime:
    '''Current time in the given timezone (as a naive local datetime).'''
    offset = tz_offset_hours(tz_name)
    return datetime.now(timezone.utc) + timedelta(hours=offset)


# =====================================================================
# PERIOD NORMALIZATION
# =====================================================================

def normalize_period(period: Dict) -> Optional[Dict]:
    '''Validate + normalize one availability period.

    Accepted shapes:
      {'day': 'monday', 'start': '16:00', 'end': '22:00'}
      {'day': 'weekday', ...}   -> expands to Mon-Fri
      {'day': 'weekend', ...}   -> expands to Sat-Sun
      {'day': 'daily', ...}     -> all 7 days

    Returns the normalized {'day','start','end'} dict, or None if invalid.
    '''
    if not isinstance(period, dict):
        return None
    day = str(period.get('day', '')).strip().lower()
    start = str(period.get('start', '')).strip()
    end = str(period.get('end', '')).strip()
    if not (start and end):
        return None
    if not _valid_time(start) or not _valid_time(end):
        return None
    if day in DAY_INDEX:
        return {'day': day, 'start': start, 'end': end}
    if day in ('weekday', 'weekdays'):
        return {'day': 'weekday', 'start': start, 'end': end}
    if day in ('weekend',):
        return {'day': 'weekend', 'start': start, 'end': end}
    if day in ('daily', 'everyday', 'all'):
        return {'day': 'daily', 'start': start, 'end': end}
    return None


def expand_periods(periods: List[Dict]) -> List[Dict]:
    '''Expand 'weekday'/'weekend'/'daily' shorthand into per-day periods.'''
    out: List[Dict] = []
    for p in periods or []:
        norm = normalize_period(p)
        if not norm:
            continue
        day = norm['day']
        if day in DAY_INDEX:
            out.append(norm)
        elif day == 'weekday':
            for d in ['monday', 'tuesday', 'wednesday', 'thursday', 'friday']:
                out.append({'day': d, 'start': norm['start'], 'end': norm['end']})
        elif day == 'weekend':
            for d in ['saturday', 'sunday']:
                out.append({'day': d, 'start': norm['start'], 'end': norm['end']})
        elif day == 'daily':
            for d in DAY_NAMES:
                out.append({'day': d, 'start': norm['start'], 'end': norm['end']})
    return out


def _valid_time(t: str) -> bool:
    '''Accept 'HH:MM' (24h).'''
    if not t or ':' not in t:
        return False
    parts = t.split(':')
    if len(parts) != 2:
        return False
    try:
        h, m = int(parts[0]), int(parts[1])
    except ValueError:
        return False
    return 0 <= h <= 23 and 0 <= m <= 59


def _time_to_minutes(t: str) -> int:
    h, m = t.split(':')
    return int(h) * 60 + int(m)


# =====================================================================
# AVAILABILITY CHECK
# =====================================================================

def is_open_at(periods: List[Dict], tz_name: str, when: Optional[datetime] = None) -> bool:
    '''True if any expanded period covers `when` (in the panel's tz).'''
    if not periods:
        return True  # no periods configured = always open
    expanded = expand_periods(periods)
    if not expanded:
        return True  # all periods were invalid; treat as always-open
    now = when or now_in_tz(tz_name)
    today = DAY_NAMES[now.weekday()]
    now_min = now.hour * 60 + now.minute
    for p in expanded:
        if p['day'] != today:
            continue
        start_min = _time_to_minutes(p['start'])
        end_min = _time_to_minutes(p['end'])
        if end_min <= start_min:
            # overnight window (e.g. 22:00-02:00): open if now >= start OR now < end
            if now_min >= start_min or now_min < end_min:
                return True
        else:
            if start_min <= now_min < end_min:
                return True
    return False


def is_panel_open_now(pdb: PremiumDB, panel: Dict, member_role_ids: Optional[List[int]] = None) -> Tuple[bool, Optional[str]]:
    '''Check whether a panel is currently open for ticket creation.

    Returns (is_open, unavailable_message). When the panel has no schedule
    or the schedule is disabled, returns (True, None). When a bypass role
    matches the member's roles, returns (True, None).
    '''
    panel_id = panel.get('panel_id') if panel else None
    if not panel_id:
        return True, None
    sched = pdb.get_schedule(panel_id)
    if not sched or not sched.get('enabled'):
        return True, None
    tz_name = sched.get('timezone') or 'UTC'
    periods = _json_loads_list(sched.get('periods'))
    if not periods:
        return True, None
    # Bypass roles
    bypass = _json_loads_list(sched.get('bypass_role_ids'))
    if bypass and member_role_ids:
        if any(int(rid) in [int(r) for r in bypass] for rid in member_role_ids):
            return True, None
    open_now = is_open_at(periods, tz_name)
    if open_now:
        return True, None
    msg = sched.get('unavailable_message') or 'Tickets are currently unavailable for this panel.'
    return False, msg


def next_open_time(pdb: PremiumDB, panel: Dict) -> Optional[str]:
    '''Human-readable 'next opens at' string, or None if always open.'''
    panel_id = panel.get('panel_id') if panel else None
    if not panel_id:
        return None
    sched = pdb.get_schedule(panel_id)
    if not sched or not sched.get('enabled'):
        return None
    tz_name = sched.get('timezone') or 'UTC'
    periods = expand_periods(_json_loads_list(sched.get('periods')))
    if not periods:
        return None
    now = now_in_tz(tz_name)
    # Search the next 7 days for the first matching open window.
    for day_offset in range(0, 8):
        candidate = now + timedelta(days=day_offset)
        today = DAY_NAMES[candidate.weekday()]
        for p in periods:
            if p['day'] != today:
                continue
            start = _time_to_minutes(p['start'])
            cand_min = candidate.hour * 60 + candidate.minute
            # If same day and start is in the future, that's our window.
            if day_offset == 0 and cand_min >= start:
                continue
            window_start = candidate.replace(
                hour=start // 60, minute=start % 60, second=0, microsecond=0
            )
            return f"{window_start.strftime('%A %H:%M')} ({tz_name})"
    return None


# =====================================================================
# CONFIG ACCESSORS (for the !schedule command)
# =====================================================================

def get_config(pdb: PremiumDB, panel_id: str) -> Optional[Dict]:
    return pdb.get_schedule_raw(panel_id)


def save_config(pdb: PremiumDB, panel_id: str, guild_id: int, *,
                timezone: str = 'UTC', periods: Optional[List[Dict]] = None,
                unavailable_message: Optional[str] = None,
                bypass_role_ids: Optional[List[int]] = None,
                enabled: bool = True) -> str:
    return pdb.upsert_schedule({
        'panel_id': panel_id,
        'guild_id': guild_id,
        'timezone': timezone,
        'periods': periods or [],
        'unavailable_message': unavailable_message,
        'bypass_role_ids': bypass_role_ids or [],
        'enabled': enabled,
    })


def disable(pdb: PremiumDB, panel_id: str) -> bool:
    return pdb.delete_schedule(panel_id)
"""

# ── TicketTool/sla.py ─────────────────────────────────────────────
_TT_sla_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.sla — Advanced SLA Tracking (Tier 1 Feature #9).

Extends Bot.py's basic SLA check (which only alerts on first-response
breach) with:
  * Two independent SLA clocks per ticket:
      - first_response SLA  (time to first staff message)
      - resolution SLA      (time to close)
  * Per-priority SLA overrides (urgent tickets get tighter targets)
  * SLA state machine:  ok -> warning -> breached  (warning fires at
    warn_before_breach_pct of the target)
  * Staff attribution: the staff member whose message triggers
    first_response_met_at is recorded.
  * Reporting: per-staff SLA performance (avg first response, avg resolution)
  * Auto-escalation hook: tickets that breach resolution SLA can be
    auto-escalated via TicketTool.escalation.

Integration:
  * TicketTool.wiring.on_ticket_create   -> create initial SLA state row
  * TicketTool.wiring.on_ticket_message  -> mark first response met
  * TicketTool.wiring.on_ticket_close    -> mark resolution met
  * TicketTool.wiring.sla_tick (every 5 min) -> advance state + warn/breach
'''

from __future__ import annotations

import logging
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, Optional, Tuple

import discord

from .db import PremiumDB


# =====================================================================
# CONFIG ACCESSORS
# =====================================================================

def get_config(pdb: PremiumDB, guild_id: int) -> Dict:
    cfg = pdb.get_sla_config(guild_id)
    if not cfg:
        return {
            'guild_id': guild_id,
            'first_response_hours': 0.0,
            'resolution_hours': 0.0,
            'urgent_first_response_hours': 0.0,
            'urgent_resolution_hours': 0.0,
            'escalation_role_id': None,
            'warn_before_breach_pct': 0,
            'enabled': 1,
        }
    return cfg


def save_config(pdb: PremiumDB, guild_id: int, cfg: Dict) -> None:
    pdb.upsert_sla_config({**cfg, 'guild_id': guild_id})


# =====================================================================
# SLA STATE LIFECYCLE
# =====================================================================

def targets_for(ticket: Dict, cfg: Dict) -> Tuple[float, float]:
    '''Return (first_response_hours, resolution_hours) for this ticket's priority.'''
    if ticket.get('priority') == 'urgent':
        fr = float(cfg.get('urgent_first_response_hours') or cfg.get('first_response_hours') or 0)
        res = float(cfg.get('urgent_resolution_hours') or cfg.get('resolution_hours') or 0)
    else:
        fr = float(cfg.get('first_response_hours') or 0)
        res = float(cfg.get('resolution_hours') or 0)
    return fr, res


def init_sla_for_ticket(pdb: PremiumDB, *, ticket: Dict, guild_id: int) -> None:
    '''Create the initial SLA state row for a new ticket (called on create).'''
    cfg = get_config(pdb, guild_id)
    if not cfg.get('enabled'):
        return
    fr_hours, res_hours = targets_for(ticket, cfg)
    now = datetime.now(timezone.utc)
    created = _parse_iso(ticket.get('created_at')) or now
    fr_due = (created + timedelta(hours=fr_hours)).isoformat() if fr_hours else None
    res_due = (created + timedelta(hours=res_hours)).isoformat() if res_hours else None
    pdb.upsert_sla_state({
        'ticket_id': ticket.get('ticket_id'),
        'guild_id': guild_id,
        'first_response_due_at': fr_due,
        'first_response_met_at': None,
        'resolution_due_at': res_due,
        'resolution_met_at': None,
        'breach_state': 'ok',
        'last_notified_at': None,
    })


def mark_first_response(pdb: PremiumDB, *, ticket_id: str) -> None:
    '''Record that the first staff response has occurred.'''
    state = pdb.get_sla_state(ticket_id)
    if not state:
        return
    if state.get('first_response_met_at'):
        return  # already met
    state['first_response_met_at'] = datetime.now(timezone.utc).isoformat()
    pdb.upsert_sla_state(state)


def mark_resolution_met(pdb: PremiumDB, *, ticket_id: str) -> None:
    state = pdb.get_sla_state(ticket_id)
    if not state:
        return
    state['resolution_met_at'] = datetime.now(timezone.utc).isoformat()
    pdb.upsert_sla_state(state)


# =====================================================================
# PERIODIC CHECK (called from wiring.sla_tick)
# =====================================================================

async def check_breaches(bot, pdb: PremiumDB, *, guild: discord.Guild) -> Dict[str, int]:
    '''Advance the SLA state of every open ticket in the guild.

    Returns {'warned': n, 'breached': n}. Pings the escalation role on breach
    and (optionally) auto-escalates the ticket.
    '''
    cfg = get_config(pdb, guild.id)
    if not cfg.get('enabled'):
        return {'warned': 0, 'breached': 0}
    tt = getattr(bot, 'ticket_tool', None)
    if tt is None:
        return {'warned': 0, 'breached': 0}
    warned = 0
    breached = 0
    now = datetime.now(timezone.utc)
    warn_pct = int(cfg.get('warn_before_breach_pct', 0) or 0)

    for state in pdb.list_open_sla_states(guild.id):
        ticket = tt.data_manager.load_ticket(state['ticket_id'])
        if not ticket or ticket.get('status') != 'open':
            continue
        # PAUSED TICKETS (Ticket Tool /pause): excluded from ALL automatic
        # actions — skip SLA warning/breach notifications while paused.
        try:
            from . import automations as _auto_mod
            if _auto_mod.is_ticket_paused(ticket):
                continue
        except Exception:
            pass
        channel = guild.get_channel(int(ticket.get('channel_id') or 0))

        # --- First-response SLA ---
        if not state.get('first_response_met_at') and state.get('first_response_due_at'):
            fr_due = _parse_iso(state['first_response_due_at'])
            if fr_due:
                if now >= fr_due:
                    # BREACH
                    if state.get('breach_state') != 'breached':
                        await _notify_breach(bot, guild, channel, ticket, cfg,
                                              kind='first_response', now=now)
                        state['breach_state'] = 'breached'
                        state['last_notified_at'] = now.isoformat()
                        pdb.upsert_sla_state(state)
                        breached += 1
                elif warn_pct > 0:
                    warn_at = fr_due - timedelta(hours=(fr_due - _parse_iso(ticket.get('created_at')) or now).total_seconds()/3600 * (100 - warn_pct) / 100)
                    # Simpler: warn when remaining < warn_pct% of total window.
                    created = _parse_iso(ticket.get('created_at')) or now
                    total = (fr_due - created).total_seconds()
                    elapsed = (now - created).total_seconds()
                    if total > 0 and elapsed / total >= (warn_pct / 100.0):
                        if state.get('breach_state') == 'ok':
                            await _notify_warning(bot, guild, channel, ticket, cfg,
                                                  kind='first_response', now=now)
                            state['breach_state'] = 'warning'
                            state['last_notified_at'] = now.isoformat()
                            pdb.upsert_sla_state(state)
                            warned += 1

        # --- Resolution SLA ---
        if not state.get('resolution_met_at') and state.get('resolution_due_at'):
            res_due = _parse_iso(state['resolution_due_at'])
            if res_due and now >= res_due:
                if state.get('breach_state') != 'breached':
                    await _notify_breach(bot, guild, channel, ticket, cfg,
                                          kind='resolution', now=now)
                    state['breach_state'] = 'breached'
                    state['last_notified_at'] = now.isoformat()
                    pdb.upsert_sla_state(state)
                    breached += 1
                    # Auto-escalate on resolution breach?
                    from . import escalation as esc
                    route = esc.get_route(pdb, ticket.get('panel_id'))
                    if route and route.get('auto_escalate_hours'):
                        await esc.escalate_ticket(
                            bot=bot, pdb=pdb, channel=channel, ticket=ticket,
                            guild=guild, escalated_by=None,
                            reason='Auto-escalated: resolution SLA breached',
                        )
    return {'warned': warned, 'breached': breached}


async def _notify_warning(bot, guild, channel, ticket, cfg, *, kind, now):
    if channel is None:
        return
    role_mention = ''
    rid = cfg.get('escalation_role_id')
    if rid:
        role_mention = f"<@&{rid}> "
    try:
        await channel.send(
            f"⏰ **SLA Warning** — {role_mention}the {kind.replace('_',' ')} SLA "
            f"window is almost over for ticket `{ticket.get('ticket_id')}`.",
            allowed_mentions=discord.AllowedMentions(roles=True),
        )
    except discord.HTTPException:
        pass


async def _notify_breach(bot, guild, channel, ticket, cfg, *, kind, now):
    if channel is None:
        return
    role_mention = '@here'
    rid = cfg.get('escalation_role_id')
    if rid:
        role_mention = f"<@&{rid}>"
    try:
        await channel.send(
            f"🚨 **SLA Breach ({kind.replace('_',' ')})** — {role_mention} "
            f"ticket `{ticket.get('ticket_id')}` has breached its "
            f"{kind.replace('_',' ')} SLA. Please respond immediately.",
            allowed_mentions=discord.AllowedMentions(roles=True, everyone=True),
        )
    except discord.HTTPException:
        pass


# =====================================================================
# REPORTING
# =====================================================================

def sla_report(pdb: PremiumDB, *, guild_id: int) -> Dict:
    '''Aggregate SLA stats for /slaconfig report.

    Returns:
      {'first_response_met': n, 'first_response_breached': n,
       'resolution_met': n, 'resolution_breached': n,
       'avg_first_response_minutes': float|None,
       'avg_resolution_minutes': float|None}
    '''
    states = pdb.list_open_sla_states(guild_id)
    # That method returns only unresolved; for reporting we want all-time, so
    # query the table directly via the connection.
    conn = pdb.dm._connection
    cur = conn.cursor()
    cur.execute('SELECT * FROM ticket_sla_state WHERE guild_id = ?', (guild_id,))
    all_states = [dict(r) for r in cur.fetchall()]
    fr_met = sum(1 for s in all_states if s.get('first_response_met_at'))
    fr_breached = sum(1 for s in all_states if s.get('breach_state') == 'breached'
                      and not s.get('first_response_met_at'))
    res_met = sum(1 for s in all_states if s.get('resolution_met_at'))
    res_breached = sum(1 for s in all_states if s.get('breach_state') == 'breached'
                       and not s.get('resolution_met_at'))

    cur.execute('SELECT ticket_id, created_at, first_response_at, closed_at FROM tickets WHERE guild_id = ?', (guild_id,))
    tickets = {r['ticket_id']: dict(r) for r in cur.fetchall()}

    fr_mins = []
    res_mins = []
    for s in all_states:
        t = tickets.get(s['ticket_id'])
        if not t:
            continue
        created = _parse_iso(t.get('created_at'))
        fr_met_at = _parse_iso(s.get('first_response_met_at'))
        if created and fr_met_at:
            fr_mins.append((fr_met_at - created).total_seconds() / 60.0)
        closed = _parse_iso(t.get('closed_at'))
        if created and closed:
            res_mins.append((closed - created).total_seconds() / 60.0)

    return {
        'first_response_met': fr_met,
        'first_response_breached': fr_breached,
        'resolution_met': res_met,
        'resolution_breached': res_breached,
        'avg_first_response_minutes': round(sum(fr_mins)/len(fr_mins), 2) if fr_mins else None,
        'avg_resolution_minutes': round(sum(res_mins)/len(res_mins), 2) if res_mins else None,
    }


# =====================================================================
# HELPERS
# =====================================================================

def _parse_iso(s) -> Optional[datetime]:
    if not s:
        return None
    try:
        return datetime.fromisoformat(str(s).replace('Z', '+00:00'))
    except (TypeError, ValueError):
        return None
"""

# ── TicketTool/staff_threads.py ─────────────────────────────────────────────
_TT_staff_threads_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.staff_threads — Private Staff Discussion Threads (Tier 2 Feature #22).

Creates a private sub-thread inside each ticket channel (or thread) for staff
to discuss the ticket without the ticket creator seeing the conversation.

  🎫 Ticket Channel (creator can see)
  └── 🔒 Staff Discussion (only staff can see)

Builds on the existing ticket_notes system (which is text-only notes): staff
discussion threads are real Discord threads, so they support real-time back-
and-forth, pinned messages, and message history.

Per-panel config:
  ticket_panels.create_staff_thread — 0/1: auto-create a staff thread on
                                       ticket open

Integration:
  * TicketTool.wiring.on_ticket_create -> staff_threads.create_for_ticket(...)
    after the ticket channel exists.
  * TicketTool.wiring.on_ticket_close  -> staff_threads.archive_for_ticket(...)
    before the channel is deleted.
  * Staff-only visibility: the thread is created as a private thread whose
    initial overwrites exclude the ticket creator and @everyone, and include
    only the support role + admins.
'''

from __future__ import annotations

import logging
from typing import Any, Dict, Optional

import discord

from .db import PremiumDB


STAFF_THREAD_PREFIX = "🔒-staff-"


# =====================================================================
# PANEL CONFIG
# =====================================================================

def should_create_staff_thread(panel: Optional[Dict]) -> bool:
    if not panel:
        return False
    return bool(int(panel.get('create_staff_thread', 0) or 0))


def configure_panel(pdb: PremiumDB, data_manager, panel_id: str, *,
                    enabled: bool) -> bool:
    try:
        panel = data_manager.load_ticket_panel(panel_id)
        if not panel:
            return False
        panel['create_staff_thread'] = 1 if enabled else 0
        data_manager.save_ticket_panel(panel)
        return True
    except Exception as exc:
        logging.warning(f"[staff_threads] configure_panel failed: {exc}")
        return False


# =====================================================================
# STAFF THREAD LIFECYCLE
# =====================================================================

async def create_for_ticket(
    *,
    ticket_channel: discord.TextChannel,
    ticket: Dict,
    panel: Optional[Dict],
    support_role_id: Optional[int] = None,
) -> Optional[discord.Thread]:
    '''Create a private staff discussion thread inside a ticket channel.

    The thread is created as a private thread (so the ticket creator can't see
    it even if they have view_channel on the parent). Staff (support role +
    admins) are added explicitly. Returns the thread object, or None on failure.
    '''
    guild = ticket_channel.guild
    ticket_id = ticket.get('ticket_id', 'unknown')
    thread_name = f"{STAFF_THREAD_PREFIX}{ticket_id}"[:100]
    try:
        # private_thread type makes the thread invisible to anyone not added.
        staff_thread = await ticket_channel.create_thread(
            name=thread_name,
            type=discord.ChannelType.private_thread,
            invitable=False,
            auto_archive_duration=10080,
            reason=f"Staff discussion for ticket {ticket_id}",
        )
    except discord.Forbidden:
        logging.warning(f"[staff_threads] no permission to create thread in #{ticket_channel.name}")
        return None
    except discord.HTTPException as exc:
        logging.warning(f"[staff_threads] create thread failed: {exc}")
        return None

    # Add all support-role members + admins to the staff thread.
    added = 0
    for member in guild.members:
        if member.bot:
            continue
        try:
            if member.guild_permissions.administrator:
                await staff_thread.add_user(member)
                added += 1
                continue
            if support_role_id:
                role = guild.get_role(int(support_role_id))
                if role and role in member.roles:
                    await staff_thread.add_user(member)
                    added += 1
        except (discord.HTTPException, discord.Forbidden):
            continue
    # Post an intro message so the thread isn't empty.
    try:
        await staff_thread.send(
            embed=discord.Embed(
                title="🔒 Staff Discussion",
                description=(
                    f"This private thread is for staff discussion of ticket `{ticket_id}`.\n"
                    f"The ticket creator **cannot see** messages here.\n\n"
                    f"Use this for: internal notes, coordinating hand-offs, discussing sensitive info.\n"
                    f"For permanent visible notes the user can read later, use `/note`."
                ),
                color=discord.Color(0x2f3136),
            )
        )
    except discord.HTTPException:
        pass
    logging.info(f"[staff_threads] created staff thread for {ticket_id} ({added} staff added)")
    return staff_thread


async def archive_for_ticket(staff_thread: discord.Thread, *, reason: str = "Ticket closed") -> None:
    '''Archive + lock the staff discussion thread when the ticket closes.'''
    try:
        await staff_thread.edit(archived=True, locked=True, reason=reason)
    except discord.HTTPException as exc:
        logging.warning(f"[staff_threads] archive failed: {exc}")


# =====================================================================
# LOOKUP
# =====================================================================

async def find_staff_thread(channel: discord.TextChannel, ticket_id: str) -> Optional[discord.Thread]:
    '''Find the staff discussion thread for a ticket by its naming convention.'''
    expected = f"{STAFF_THREAD_PREFIX}{ticket_id}"[:100]
    try:
        async for thread in channel.archived_threads(private=True, limit=50):
            if thread.name == expected:
                return thread
    except (discord.HTTPException, discord.Forbidden):
        pass
    # Also check active threads.
    try:
        for thread in channel.threads:
            if thread.name == expected:
                return thread
    except (AttributeError, discord.HTTPException):
        pass
    return None
"""

# ── TicketTool/thread_tickets.py ─────────────────────────────────────────────
_TT_thread_tickets_SRC = r"""
# -*- coding: utf-8 -*-
'''
TicketTool.thread_tickets — Thread-Based Tickets (Tier 2 Feature #21).

Creates tickets as private Discord THREADS instead of channels. Useful when:
  * A server generates many tickets (threads don't count against Discord's
    500-channel-per-guild limit).
  * Tickets should be grouped under a single parent channel per panel.

Per-panel config (stored on ticket_panels via the Tier 2 migrations):
  use_threads                  — 0/1: create threads instead of channels
  thread_parent_channel_id     — the parent channel to create threads under
  allow_user_invite_in_thread  — 0/1: can non-staff invite others into the
                                 thread

Integration:
  * TicketTool.wiring.on_ticket_create checks panel.use_threads and, if true,
    calls create_thread_ticket() instead of letting Bot.py create a channel.
  * The thread is created private (invited members only); the support role
    is added; the creator is added automatically by Discord on creation.

Notes:
  * discord.py 2.4 supports create_thread on a TextChannel (creates a public
    thread) or a ForumChannel (creates a forum post). For private support
    tickets we use a private thread (archived=False, invitable=True) under a
    regular text channel.
  * Thread tickets are stored in the tickets table with is_thread=1 and
    thread_id = the thread's message-id (channel-ids and thread-ids share a
    namespace in Discord, so channel_id is reused for the thread id).
'''

from __future__ import annotations

import logging
from typing import Any, Dict, Optional, Tuple

import discord

from .db import PremiumDB


# =====================================================================
# PANEL CONFIG HELPERS
# =====================================================================

def is_thread_panel(panel: Optional[Dict]) -> bool:
    if not panel:
        return False
    return bool(int(panel.get('use_threads', 0) or 0))


def get_thread_parent(panel: Dict, guild: discord.Guild) -> Optional[discord.TextChannel]:
    parent_id = panel.get('thread_parent_channel_id')
    if not parent_id:
        return None
    try:
        ch = guild.get_channel(int(parent_id))
    except (TypeError, ValueError):
        return None
    if isinstance(ch, discord.TextChannel):
        return ch
    return None


# =====================================================================
# THREAD TICKET CREATION
# =====================================================================

async def create_thread_ticket(
    *,
    guild: discord.Guild,
    user: discord.Member,
    panel: Dict,
    ticket_id: str,
    channel_name: str,
    support_role_id: Optional[int] = None,
    allow_user_invite: bool = False,
) -> Tuple[Optional[discord.Thread], Optional[str]]:
    '''Create a private thread as a ticket.

    Returns (thread, error_message). On success, the thread's id IS the
    channel_id stored on the ticket row (Discord shares the id namespace).
    '''
    parent = get_thread_parent(panel, guild)
    if parent is None:
        return None, "This panel is configured for thread tickets but has no parent channel set."

    # Build the thread. discord.py 2.4: parent.create_thread(...) creates a
    # thread under the parent text channel. We use type=discord.ChannelType.private_thread
    # so only invited members can see it.
    try:
        thread = await parent.create_thread(
            name=channel_name[:100],
            type=discord.ChannelType.private_thread,
            invitable=bool(allow_user_invite),  # False = only staff can invite
            auto_archive_duration=10080,  # 7 days (max); the bot keeps it alive
            reason=f"Ticket {ticket_id} for {user}",
        )
    except discord.Forbidden:
        return None, "I don't have permission to create threads in that channel."
    except discord.HTTPException as exc:
        return None, f"Failed to create thread: {exc}"

    # Add the support role's members to the thread (the creator is auto-added).
    if support_role_id:
        try:
            support_role = guild.get_role(int(support_role_id))
            if support_role:
                for member in support_role.members:
                    if member.bot:
                        continue
                    try:
                        await thread.add_user(member)
                    except (discord.HTTPException, discord.Forbidden):
                        pass  # best-effort
        except Exception as exc:
            logging.warning(f"[thread_tickets] add support role failed: {exc}")

    # Ensure the bot itself is in the thread (it should be automatically,
    # but this is a safety net).
    try:
        await thread.add_user(guild.me)
    except (discord.HTTPException, discord.Forbidden):
        pass

    return thread, None


# =====================================================================
# THREAD TICKET CLOSE
# =====================================================================

async def archive_thread_ticket(thread: discord.Thread, *, reason: str = "Ticket closed") -> None:
    '''Archive + lock a thread ticket (instead of deleting the channel).'''
    try:
        await thread.edit(archived=True, locked=True, reason=reason)
    except discord.HTTPException as exc:
        logging.warning(f"[thread_tickets] archive failed: {exc}")


# =====================================================================
# CONFIG COMMANDS HELPERS
# =====================================================================

def configure_panel_for_threads(pdb: PremiumDB, data_manager,
                                 panel_id: str, guild_id: int, *,
                                 enabled: bool, parent_channel_id: Optional[int],
                                 allow_user_invite: bool = False) -> bool:
    '''Update the panel's thread-ticket config columns.'''
    try:
        panel = data_manager.load_ticket_panel(panel_id)
        if not panel:
            return False
        panel['use_threads'] = 1 if enabled else 0
        panel['thread_parent_channel_id'] = parent_channel_id
        panel['allow_user_invite_in_thread'] = 1 if allow_user_invite else 0
        data_manager.save_ticket_panel(panel)
        return True
    except Exception as exc:
        logging.warning(f"[thread_tickets] configure_panel_for_threads failed: {exc}")
        return False
"""

