# --- MODERATION COMMANDS ---
@bot.command()
@commands.has_permissions(kick_members=True)
async def kick(ctx: commands.Context, members: commands.Greedy[discord.Member], *, reason: str = "No reason provided") -> None:
    """Kicks one or multiple members. Usage: !kick @user1 @user2 [reason]"""
    if not members:
        await ctx.send("Usage: `!kick @user1 @user2 [reason]` (or `!kick @user1, @user2`)")
        return

    kicked_list = []
    failed_list = []

    for member in members:
        if member.top_role >= ctx.guild.me.top_role or member.id == ctx.guild.owner_id:
            failed_list.append(f"{member.mention} (Hierarchy/Owner)")
            continue
        try:
            await member.kick(reason=f"Kicked by {ctx.author}: {reason}")
            kicked_list.append(member.mention)
        except discord.Forbidden:
            failed_list.append(f"{member.mention} (Missing Perms)")
        except discord.HTTPException:
            failed_list.append(f"{member.mention} (API Error)")

    embed = EmbedBuilder.success("Mass Kick Complete", "")
    if kicked_list:
        embed.add_field(name="✅ Successfully Kicked", value="\n".join(kicked_list), inline=False)
    if failed_list:
        embed.add_field(name="❌ Failed to Kick", value="\n".join(failed_list), inline=False)
    
    embed.description = f"**Reason:** {reason}"
    await ctx.send(embed=embed)
    logging.info(f'User(s) {kicked_list} were kicked by {ctx.author} for: {reason}')


@bot.command()
@commands.has_permissions(ban_members=True)
async def ban(ctx: commands.Context, members: commands.Greedy[discord.Member], *, reason: str = "No reason provided") -> None:
    """Bans one or multiple members. Usage: !ban @user1 @user2 [reason]"""
    if not members:
        await ctx.send("Usage: `!ban @user1 @user2 [reason]` (or `!ban @user1, @user2`)")
        return

    banned_list = []
    failed_list = []

    for member in members:
        if member.top_role >= ctx.guild.me.top_role or member.id == ctx.guild.owner_id:
            failed_list.append(f"{member.mention} (Hierarchy/Owner)")
            continue
        try:
            await member.ban(reason=f"Banned by {ctx.author}: {reason}", delete_message_days=0)
            banned_list.append(member.mention)
        except discord.Forbidden:
            failed_list.append(f"{member.mention} (Missing Perms)")
        except discord.HTTPException:
            failed_list.append(f"{member.mention} (API Error)")

    embed = EmbedBuilder.success("Mass Ban Complete", "")
    if banned_list:
        embed.add_field(name="✅ Successfully Banned", value="\n".join(banned_list), inline=False)
    if failed_list:
        embed.add_field(name="❌ Failed to Ban", value="\n".join(failed_list), inline=False)
    
    embed.description = f"**Reason:** {reason}"
    await ctx.send(embed=embed)
    logging.info(f'User(s) {banned_list} were banned by {ctx.author} for: {reason}')

@bot.command()
@commands.has_permissions(ban_members=True)
async def banid(ctx: commands.Context, user_id: int, *, reason: str = "No reason provided") -> None:
    try:
        user = await bot.fetch_user(user_id)
        await ctx.guild.ban(user, reason=reason)
        await ctx.send(embed=EmbedBuilder.success("User Banned", f"**{user.name}** (ID: {user_id}) has been banned.\n**Reason:** {reason}"))
        logging.info(f'User with ID {user_id} was banned by {ctx.author} for: {reason}')
    except discord.NotFound:
        await ctx.send(f'User with ID {user_id} not found.')
    except discord.Forbidden:
        await ctx.send("I don't have permission to ban that user.")
    except discord.HTTPException:
        await ctx.send("Failed to ban the user. Please try again.")


# --- BLACKLIST COMMANDS ---
@bot.command(name="blacklist", description="Add a keyword to the blacklist")
@commands.has_permissions(administrator=True)
@app_commands.describe(keyword="The keyword to blacklist")
async def blacklist_cmd(ctx: commands.Context, *, keyword: str) -> None:
    global blacklisted_keywords
    
    keyword = keyword.strip()
    if not keyword:
        await ctx.send("Please provide a keyword to blacklist.")
        return
    
    if len(keyword) < config.limits.min_blacklist_keyword_length:
        await ctx.send(f"Keyword must be at least {config.limits.min_blacklist_keyword_length} characters long.")
        return
    
    for existing in blacklisted_keywords:
        if existing.lower() == keyword.lower():
            await ctx.send(f"Keyword `{keyword}` is already blacklisted.")
            return
    
    blacklisted_keywords.add(keyword)
    save_blacklist_data()
    
    embed = EmbedBuilder.warning(
        "Keyword Blacklisted",
        f"Added `{keyword}` to blacklist.\nTotal keywords: {len(blacklisted_keywords)}\n\n"
        f"Any user with this keyword in their profile will be auto-banned."
    )
    
    await ctx.send(embed=embed)
    logging.info(f"[Blacklist] Keyword '{keyword}' added by {ctx.author}")


@bot.command(name="unblacklist", description="Remove a keyword from the blacklist")
@commands.has_permissions(administrator=True)
@app_commands.describe(keyword="The keyword to remove from the blacklist")
async def unblacklist_cmd(ctx: commands.Context, *, keyword: str) -> None:
    global blacklisted_keywords
    
    keyword = keyword.strip()
    found_keyword = next((k for k in blacklisted_keywords if k.lower() == keyword.lower()), None)
    
    if not found_keyword:
        await ctx.send(f"Keyword `{keyword}` is not in the blacklist.")
        return
    
    blacklisted_keywords.discard(found_keyword)
    save_blacklist_data()
    
    await ctx.send(embed=EmbedBuilder.success("Keyword Removed", f"Removed `{found_keyword}` from blacklist."))
    logging.info(f"[Blacklist] Keyword '{found_keyword}' removed by {ctx.author}")


@bot.command(name="blacklistscan", description="Scan all members for blacklisted keywords")
@commands.has_permissions(administrator=True)
async def blacklistscan_cmd(ctx: commands.Context) -> None:
    if not blacklisted_keywords:
        await ctx.send("No keywords are currently blacklisted. Use `/blacklist <keyword>` to add some.")
        return
    
    status_msg = await ctx.send(f"Scanning **{ctx.guild.member_count}** members for **{len(blacklisted_keywords)}** blacklisted keyword(s)...")
    
    banned_count, failed_count, matches = await scan_and_ban_blacklisted_members(ctx.guild)
    await status_msg.delete()
    
    embed = EmbedBuilder.warning(
        "Blacklist Scan Complete",
        f"**Members Scanned:** {ctx.guild.member_count}\n"
        f"**Members Banned:** {banned_count}\n"
        f"**Failed to Ban:** {failed_count}"
    )
    
    if matches:
        match_text = ""
        for match in matches[:5]:
            match_text += f"- {match['user'].name} - \"{match['keyword']}\" in {match['location']}\n"
        if len(matches) > 5:
            match_text += f"... and {len(matches) - 5} more"
        embed.add_field(name="Matches Found", value=match_text, inline=False)
    
    await ctx.send(embed=embed)
    logging.info(f"[Blacklist] Scan complete by {ctx.author}. Banned: {banned_count}, Failed: {failed_count}")


@bot.command(name="blacklistlist", description="Display all blacklisted keywords")
@commands.has_permissions(administrator=True)
async def blacklistlist_cmd(ctx: commands.Context) -> None:
    if not blacklisted_keywords:
        await ctx.send("**No keywords are currently blacklisted.**")
        return
    
    keywords_list = list(blacklisted_keywords)
    embed = discord.Embed(title="Blacklisted Keywords", color=discord.Color.red())
    
    chunks = [keywords_list[i:i+20] for i in range(0, len(keywords_list), 20)]
    for i, chunk in enumerate(chunks[:5]):
        field_name = "Keywords" if i == 0 else "Keywords (continued)"
        embed.add_field(name=field_name, value="\n".join(f"- `{kw}`" for kw in chunk), inline=False)
    
    if len(chunks) > 5:
        embed.add_field(name="...", value=f"And {len(keywords_list) - 100} more keywords", inline=False)
    
    embed.set_footer(text=f"Total: {len(blacklisted_keywords)} keyword(s)")
    await ctx.send(embed=embed)


@bot.command(name="checkprofile", description="Check a user's profile for blacklisted keywords")
@app_commands.describe(member="The member to check")
async def checkprofile_cmd(ctx: commands.Context, member: Optional[discord.Member] = None) -> None:
    if member is None:
        member = ctx.author
    
    is_blacklisted, keyword, location = await check_user_profile_for_blacklist(member)
    
    embed = discord.Embed(title=f"Profile Check: {member.display_name}", color=discord.Color.red() if is_blacklisted else discord.Color.green())
    embed.set_thumbnail(url=member.avatar.url if member.avatar else member.default_avatar.url)
    
    if is_blacklisted:
        embed.add_field(name="Status", value="**BLACKLISTED**", inline=True)
        embed.add_field(name="Matched Keyword", value=f"**{keyword}**", inline=True)
        embed.add_field(name="Location", value=location, inline=True)
    else:
        embed.add_field(name="Status", value="**Clean**", inline=True)
        embed.add_field(name="Keywords Checked", value=str(len(blacklisted_keywords)), inline=True)
    
    await ctx.send(embed=embed)


# --- RULES EMBED HELPERS ---
# Build a Discohook-style embed (or a small list of paginated embeds) from raw
# rules text. The text goes straight into the embed description, so Discord
# renders Markdown (bold/italic/code/blockquotes/links) exactly the way the
# admin formatted it. Pagination kicks in automatically past Discord's 4096-char
# description limit so long rulesets are never silently truncated.
def _build_rules_embeds(
    title: Optional[str],
    rules_text: str,
    color: discord.Color,
    footer_text: str,
) -> List[discord.Embed]:
    if not rules_text:
        return [discord.Embed(title=title, description="No rules available. Contact staff.", color=color)]
    pages = split_rules_into_pages(rules_text, max_chars=3900)
    # Discord caps a single message at 10 embeds. Cap the pages and fold the
    # overflow into the 10th page so no rules are lost.
    if len(pages) > 10:
        pages = pages[:9] + ["\n\n---\n\n".join(pages[9:])]
    total = len(pages)
    embeds: List[discord.Embed] = []
    for i, page in enumerate(pages, start=1):
        e = discord.Embed(
            title=title if i == 1 else None,  # only the first page shows the title
            description=page,
            color=color,
        )
        e.set_footer(text=f"{footer_text} • Page {i}/{total}" if total > 1 else footer_text)
        e.timestamp = datetime.now(timezone.utc)
        embeds.append(e)
    return embeds


async def _post_or_edit_rules_embed(
    channel: Optional[discord.TextChannel],
    existing_message_id: int,
    title: Optional[str],
    rules_text: str,
    color: discord.Color,
    footer_text: str,
) -> Tuple[Optional[int], str]:
    """Post (or edit) a formatted rules embed in the given channel.

    Returns (message_id, status) where status is:
      'posted'   — a new message was created
      'edited'   — the existing message was updated in place
      'error: …'  — something went wrong (channel missing, no perms, etc.)
    """
    if channel is None:
        return None, "error: Rules channel is not set. Run `!updategangrules #channel <message_id>` or `!channelsetup` first."
    if not isinstance(channel, discord.TextChannel):
        return None, "error: The configured rules channel is not a text channel."

    embeds = _build_rules_embeds(title, rules_text, color, footer_text)

    # Prefer editing the existing rules message so the channel doesn't fill up
    # with a new embed every time the admin refreshes the rules.
    if existing_message_id:
        try:
            message = await channel.fetch_message(existing_message_id)
            await message.edit(embeds=embeds)
            return message.id, "edited"
        except discord.NotFound:
            pass  # old message was deleted — fall through to posting a new one
        except discord.Forbidden:
            return None, "error: No permission to edit messages in the rules channel."
        except Exception as e:
            logging.warning(f"[RulesEmbed] Could not edit existing rules message {existing_message_id}: {e}")

    try:
        message = await channel.send(embeds=embeds)
        return message.id, "posted"
    except discord.Forbidden:
        return None, "error: No permission to send embeds in the rules channel."
    except Exception as e:
        return None, f"error: {e}"


# --- RULES MANAGEMENT COMMANDS ---
@bot.command(name="updategangrules", description="Fetch & cache the gang rules from a channel message")
@commands.has_permissions(administrator=True)
async def updategangrules_cmd(
    ctx: commands.Context,
    channel: Optional[discord.TextChannel] = None,
    message_id: Optional[str] = None,
) -> None:
    """Fetch the gang rules message and cache it.

    Without arguments: uses the configured gang_rules_channel + gang_rules_message.
    With channel + message_id: fetches that specific message AND persists the
    channel/message IDs so future !updategangrules (no args) re-fetches it.

    Examples:
      !updategangrules                                  # use configured source
      !updategangrules #rules-chat 1539152833226743910  # fetch a specific message
    """
    try:
        # If a channel + message ID were provided, resolve & persist them.
        if channel is not None or message_id:
            if channel is None or not message_id:
                await ctx.send(brand_text(
                    "Please provide BOTH a channel and a message ID.\n"
                    "Example: `!updategangrules #rules-chat 1539152833226743910`"
                ))
                return
            mid = message_id.strip().strip("`")
            # Accept a full Discord message link too: .../channel_id/message_id
            if "/" in mid:
                mid = mid.split("/")[-1]
            if not mid.isdigit():
                await ctx.send(brand_text(
                    "`message_id` must be a numeric message ID (or a full Discord message link).\n"
                    "Example: `!updategangrules #rules-chat 1539152833226743910`"
                ))
                return
            config.servers.gang_rules_channel = channel.id
            config.servers.gang_rules_message = int(mid)
            config.save_channel_settings()

        target_channel = bot.get_channel(config.servers.gang_rules_channel)
        if not target_channel:
            await ctx.send(brand_text(
                "[GANG ABBR] rules channel not found.\n"
                "Set it with `!updategangrules #channel <message_id>` or via `!channelsetup`."
            ))
            return
        message = await target_channel.fetch_message(config.servers.gang_rules_message)
        # Recover the rules text whether the source is a plain message OR an
        # embed-only message (e.g. one posted by /setgangrules). For paginated
        # embeds, concatenate all embed descriptions back together.
        rules_text = message.content or ""
        if not rules_text and message.embeds:
            rules_text = "\n\n".join((e.description or "") for e in message.embeds)
        rules_cache['gang_rules'] = rules_text
        rules_cache['gang_last_updated'] = datetime.now(timezone.utc).isoformat()
        save_rules_cache()

        embed = EmbedBuilder.success(
            brand_text("[GANG ABBR] Rules Updated"),
            brand_text(
                f"Successfully cached the [GANG ABBR] rules.\n"
                f"**Source:** {target_channel.mention}\n"
                f"**Message ID:** `{config.servers.gang_rules_message}`\n"
                f"**Characters:** {len(rules_text)}"
            )
        )
        await ctx.send(embed=embed)
        logging.info(f"[RulesCache] Gang rules updated by {ctx.author} (channel={target_channel.id}, msg={config.servers.gang_rules_message})")
    except discord.NotFound:
        await ctx.send(brand_text(
            "[GANG ABBR] rules message not found. Double-check the message ID — "
            "it must be a message that exists in the configured channel."
        ))
    except discord.Forbidden:
        await ctx.send(brand_text("No permission to fetch the [GANG ABBR] rules message."))
    except Exception as e:
        await ctx.send(f"Error: {str(e)}")


